ENTRY [{"id": "human-medicine-mitral-valve-location", "topicId": "human-medicine", "sourceOrder": 17, "status": "READY_FOR_INDEPENDENT_REVIEW", "literalGroups": [{"group": "prompt_ordered_answers_key", "literal": {"prompt": "Между какими структурами сердца расположен митральный клапан?", "answers": ["Правым предсердием и правым желудочком", "Левым желудочком и аортой", "Правым желудочком и лёгочным стволом", "Левым предсердием и левым желудочком"], "correctIndex": 3}, "literalSHA256": "fedab46898caa9a161aae412ad73ebfbc778bd276ae40fe29cfcde292d1fa0fb", "primaryGround": "The mitral valve guards the left-atrium/left-ventricle opening (L147-L148, L159). The other options are genuine valve junctions: right atrium/right ventricle (L136, L154), left ventricle/aorta (L152, L160), and right ventricle/pulmonary trunk (L145, L157-L158); the mitral identity makes the key unique.", "sourcePaths": ["docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy.json", "docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy-middle.json", "docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy-tail.json"], "locator": "L136, L145, L147-L148, L152, L154-L160"}, {"group": "explanation", "literal": "Митральный, или двустворчатый, клапан расположен между левым предсердием и левым желудочком. При сокращении левого желудочка он закрывается и препятствует обратному току крови в левое предсердие.", "literalSHA256": "17861dd9ff5202ab778ef4967e2c1da601dd19b98f9e00fffc0dbabaed45f6d4", "primaryGround": "The left atrium opens into the left ventricle through the mitral valve (L147-L148, L159). During ventricular contraction, the mitral cusps close and papillary muscles/chordae help prevent them from being forced back into the atrium (L167-L168).", "sourcePaths": ["docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy.json", "docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy-middle.json"], "locator": "L147-L148, L159, L167-L168"}, {"group": "note0", "literal": "Трёхстворчатый клапан обычно состоит из трёх створок и находится между правым предсердием и правым желудочком.", "literalSHA256": "8c0443a9d5d819d5d707465e51478d84bb33826f50307dcee73f6ad8c9bc8393", "primaryGround": "The tricuspid valve guards the right atrium/right ventricle opening and normally has three leaflets (L136, L154).", "sourcePaths": ["docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy.json", "docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy-middle.json"], "locator": "L136, L154"}, {"group": "note1", "literal": "Аортальный клапан находится у выхода из левого желудочка в аорту и препятствует обратному току крови.", "literalSHA256": "2732d417e1f886c1451bf8ed1d7c793e04c6b406df41eb4019c58b78c7ca8eb3", "primaryGround": "The left ventricle ejects blood into the aorta through the aortic semilunar valve (L152); the valve at the aortic base prevents backflow (L160).", "sourcePaths": ["docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy-middle.json"], "locator": "L152, L160"}, {"group": "note2", "literal": "Клапан лёгочного ствола расположен у его основания и предотвращает обратный ток крови в правый желудочек.", "literalSHA256": "ef6aa7b4533e4376b18244a9f0941f31e34d8e4b1ac27dd0eb3ee86736cb5a65", "primaryGround": "The pulmonary semilunar valve is at the base of the pulmonary trunk (L145, L157) and closes against backflow toward the ventricle (L157-L158).", "sourcePaths": ["docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy.json", "docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy-middle.json"], "locator": "L145, L157-L158"}, {"group": "note3", "literal": "У митрального клапана две створки; в клинике его обычно называют митральным, а не двустворчатым.", "literalSHA256": "494865a77c2e5ba1fe4557f5fae92cc9e2973c18ce413035ce53b26fe205119f", "primaryGround": "The mitral valve has two cusps and is also called the bicuspid or left atrioventricular valve; clinical usage favors “mitral” (L159).", "sourcePaths": ["docs/content-audits/question-quality-wave-8/coordinator-01a1661f/source-human-medicine11/raw/openstax-heart-anatomy-middle.json"], "locator": "L159"}], "fourFullPromptAnswerNoteAssessments": [{"slot": 0, "fullPrompt": "Между какими структурами сердца расположен митральный клапан?", "answer": "Правым предсердием и правым желудочком", "note": "Трёхстворчатый клапан обычно состоит из трёх створок и находится между правым предсердием и правым желудочком.", "grammar": "“Межд

